// Simple running counters for human-friendly invoice/offer IDs
function nextSequence(db, key) {
  db.sequences = db.sequences || {};
  db.sequences[key] = (db.sequences[key] || 0) + 1;
  return db.sequences[key];
}

async function authMiddleware(req, res, next) {
  const header = req.headers.authorization;
  if (!header) return res.status(401).json({ error: 'Not authenticated' });
  const token = header.replace('Bearer ', '');
  try {
    req.userEmail = jwt.verify(token, JWT_SECRET).email;
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired session, please log in again' });
  }
  // Re-check disqualification on every request, not just at login — an admin
  // can disqualify someone mid-session and it takes effect immediately.
  try {
    const db = await readDB();
    const user = db.users.find(u => u.email === req.userEmail);
    if (user && user.disqualified) {
      return res.status(403).json({ error: `Your account has been disqualified${user.disqualifiedReason ? ': ' + user.disqualifiedReason : ''}. Contact support if you believe this is a mistake.` });
    }
  } catch (e) {
    console.error('[authMiddleware] disqualification check failed:', e.message);
    // Fail open on a DB hiccup rather than locking everyone out — the login-time
    // check and /api/me check still provide a backstop.
  }
  next();
}

// Emails listed here get admin (owner) access to the /api/admin/* routes.
// Set ADMIN_EMAILS in your environment, comma-separated, e.g.
// ADMIN_EMAILS=you@example.com,cofounder@example.com
const ADMIN_EMAILS = (process.env.ADMIN_EMAILS || '')
  .split(',').map(e => e.trim().toLowerCase()).filter(Boolean);

function isAdminEmail(email) {
  return ADMIN_EMAILS.includes((email || '').toLowerCase());
}

async function adminMiddleware(req, res, next) {
  if (!isAdminEmail(req.userEmail)) return res.status(403).json({ error: 'Admin access only' });
  next();
}

// Compresses a base64 data-URL image before storing it — payment-proof
// screenshots are small in content but large in raw size, and MongoDB
// Atlas's free tier only gives 512MB total, so this matters at real scale.
async function compressImageDataUrl(dataUrl) {
  if (!dataUrl || !dataUrl.startsWith('data:image')) return dataUrl;
  try {
    const base64 = dataUrl.split(',')[1];
    const buffer = Buffer.from(base64, 'base64');
    const compressed = await sharp(buffer)
      .resize({ width: 900, withoutEnlargement: true })
      .jpeg({ quality: 65 })
      .toBuffer();
    return `data:image/jpeg;base64,${compressed.toString('base64')}`;
  } catch (e) {
    console.error('[compressImageDataUrl] Failed to compress, storing original:', e.message);
    return dataUrl;
  }
}

