// ---------- Public certificate verification (no auth — anyone, e.g. a college, can check) ----------
app.get('/api/verify/:certId', async (req, res) => {
  const db = await readDB();
  for (const user of db.users) {
    const enrolled = Array.isArray(user.enrolled) ? user.enrolled : [];
    for (const e of enrolled) {
      if (e.certificate && e.certificate.id === req.params.certId) {
        return res.json({
          valid: true,
          certId: e.certificate.id,
          name: e.certificate.name,
          college: e.certificate.college,
          regNo: e.certificate.regNo,
          courseName: e.certificate.courseName,
          startDate: e.certificate.startDate,
          endDate: e.certificate.endDate,
          issuedAt: e.certificate.submittedAt,
        });
      }
    }
  }
  res.status(404).json({ valid: false, error: 'No certificate found with this ID' });
});

// ---------- Admin (owner-only) ----------
// Manual backup export — MongoDB Atlas's free (M0) tier has no automatic
// backups, so this lets the admin download a full JSON snapshot on demand.
// Passwords are excluded (already hashed, but no reason to include them).
app.get('/api/admin/backup', authMiddleware, adminMiddleware, async (req, res) => {
  const db = await readDB();
  const safeCopy = {
    exportedAt: new Date().toISOString(),
    users: db.users.map(u => {
      const { password, resetToken, ...safe } = u;
      return safe;
    }),
  };
  const filename = `byteforge-backup-${new Date().toISOString().slice(0, 10)}.json`;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
  res.send(JSON.stringify(safeCopy, null, 2));
});

app.get('/api/admin/students', authMiddleware, adminMiddleware, async (req, res) => {
  const db = await readDB();
  const students = db.users
    .filter(u => !isAdminEmail(u.email)) // don't list admin accounts as "students"
    .map(u => {
      const enrolled = Array.isArray(u.enrolled) ? u.enrolled.map(e => (typeof e === 'string' ? { courseId: e } : e)) : [];
      const enrichedEnrollments = enrolled.map(e => {
        const course = COURSES.find(c => c.id === e.courseId);
        const totalLessons = course && course.weeks ? course.weeks.reduce((n, w) => n + w.lessons.length, 0) : 0;
        const completedCount = (e.progress && e.progress.completed) ? e.progress.completed.length : 0;
        return {
          courseId: e.courseId,
          courseName: course ? course.name : e.courseId,
          price: course ? course.price : null,
          enrolledAt: e.enrolledAt,
          progressPct: totalLessons ? Math.round((completedCount / totalLessons) * 100) : 0,
          hasOfferLetter: !!e.offerLetter,
          hasCertificate: !!e.certificate,
        };
      });
      const totalPaid = enrichedEnrollments.reduce((sum, e) => sum + (e.price || 0), 0);
      return {
        name: u.name,
        email: u.email,
        disqualified: !!u.disqualified,
        disqualifiedReason: u.disqualifiedReason || null,
        enrolledCount: enrolled.length,
        totalPaid,
        enrollments: enrichedEnrollments,
      };
    });

  const summary = {
    totalStudents: students.length,
    totalEnrollments: students.reduce((n, s) => n + s.enrolledCount, 0),
    totalRevenue: students.reduce((n, s) => n + s.totalPaid, 0),
    disqualifiedCount: students.filter(s => s.disqualified).length,
  };
  res.json({ summary, students });
});

app.post('/api/admin/disqualify', authMiddleware, adminMiddleware, async (req, res) => {
  const { email, reason } = req.body || {};
  if (!email) return res.status(400).json({ error: 'email is required' });
  const db = await readDB();
  const user = db.users.find(u => u.email === (email || '').toLowerCase().trim());
  if (!user) return res.status(404).json({ error: 'Student not found' });
  if (isAdminEmail(user.email)) return res.status(400).json({ error: "Can't disqualify an admin account" });
  user.disqualified = true;
  user.disqualifiedReason = (reason || '').trim() || null;
  await writeDB(db);
  res.json({ success: true });
});

app.post('/api/admin/requalify', authMiddleware, adminMiddleware, async (req, res) => {
  const { email } = req.body || {};
  if (!email) return res.status(400).json({ error: 'email is required' });
  const db = await readDB();
  const user = db.users.find(u => u.email === (email || '').toLowerCase().trim());
  if (!user) return res.status(404).json({ error: 'Student not found' });
  user.disqualified = false;
  user.disqualifiedReason = null;
  await writeDB(db);
  res.json({ success: true });
});

